package factory.kit; import java.io.*;import javax.imageio.*;import javax.imageio.stream.*;import java.awt.image.*;public class GifWriterTest{public static void main(String[] args)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();int[] p=new int[32*32];java.util.Arrays.fill(p,0xffff0000);try(GifWriter w=new GifWriter(bytes,32,32)){w.frame(p,300);java.util.Arrays.fill(p,0xff0000ff);w.frame(p,500);}try(ImageInputStream in=ImageIO.createImageInputStream(new ByteArrayInputStream(bytes.toByteArray()))){ImageReader r=ImageIO.getImageReadersByFormatName("gif").next();try{r.setInput(in);if(r.getNumImages(true)!=2||r.read(0).getRGB(31,31)!=0xffff0000||r.read(1).getRGB(31,31)!=0xff0000ff)throw new AssertionError("GIF decode");}finally{r.dispose();}}System.out.println("GIF two-frame decoder test passed");}}